#!/usr/bin/env bash
# Regenerates the signed release fixtures of the update relay's host tests
# with throwaway GnuPG keys: a release key (Ed25519 primary, an Ed25519
# signing subkey without expiry and one that expires after a year), exported
# as a keyserver serves it (test_release_key.asc, with its fingerprint in
# test_release_key.h), and an unrelated key for the wrong-key case.
set -euo pipefail

here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
export GNUPGHOME="$(mktemp -d)"
trap 'gpgconf --kill all; rm -rf "$GNUPGHOME"' EXIT
gpg_batch=(gpg --batch --quiet --pinentry-mode loopback --passphrase "")

"${gpg_batch[@]}" --quick-gen-key "OS Services test release" ed25519 cert never
release_fpr="$(gpg --list-keys --with-colons "OS Services test release" |
  awk -F: '/^fpr:/ { print $10; exit }')"
"${gpg_batch[@]}" --quick-add-key "$release_fpr" ed25519 sign never
"${gpg_batch[@]}" --quick-add-key "$release_fpr" ed25519 sign 1y
# The fingerprints of the two subkeys, in the order they were added.
subkey_fpr="$(gpg --list-keys --with-colons "$release_fpr" |
  awk -F: '/^fpr:/ { n++ } /^fpr:/ && n == 2 { print $10 }')"
expiring_fpr="$(gpg --list-keys --with-colons "$release_fpr" |
  awk -F: '/^fpr:/ { n++ } /^fpr:/ && n == 3 { print $10 }')"
"${gpg_batch[@]}" --quick-gen-key "OS Services wrong key" ed25519 sign never

# 70,000 bytes: two update.chunk messages, the last one short.
python3 -c 'import sys; sys.stdout.write("".join(f"OS Services test package line {i:06d}\n" for i in range(2000))[:70000])' \
  > "$here/package.bin"
package_sha="$(sha256sum "$here/package.bin" | cut -d' ' -f1)"
cat > "$here/releases.json" <<JSON
{
  "releases": [
    {"version": "0.4.1", "packages": {
      "linux-x86_64-appimage": {"path": "0.4.1/os-services.AppImage", "size": 70000, "sha256": "$package_sha"}}},
    {"version": "0.4.3", "packages": {
      "linux-x86_64-appimage": {"path": "0.4.3/os-services-0.4.3.AppImage", "size": 70000, "sha256": "$package_sha"},
      "macos-aarch64": {"path": "../outside.tar.gz", "size": 70000, "sha256": "$package_sha"},
      "windows-x86_64": {"path": "0.4.3/setup.exe", "size": 0, "sha256": "$package_sha"}}},
    {"version": "0.5.0", "packages": {}},
    {"version": "0.4.4-rc.1", "packages": {}},
    {"version": "v0.4.2", "note": "brackets ] and braces } in \"strings\", too", "packages": {}},
    {"version": "0.4.x"}
  ],
  "generated": "for the host tests"
}
JSON
cat > "$here/releases-dev.json" <<JSON
{"releases": [
  {"version": "0.4.4-dev.2", "packages": {}},
  {"version": "0.4.4-dev.10", "packages": {
    "linux-x86_64-appimage": {"path": "dev/0.4.4-dev.10.AppImage", "size": 70000, "sha256": "$package_sha"}}},
  {"version": "0.4.5", "packages": {}}
]}
JSON

sign() { "${gpg_batch[@]}" --yes --local-user "$1" --digest-algo "$2" --output "$3" --detach-sign "$4"; }
sign "$subkey_fpr!" SHA256 "$here/releases.json.sig" "$here/releases.json"
sign "$subkey_fpr!" SHA512 "$here/releases.json.sha512.sig" "$here/releases.json"
sign "$subkey_fpr!" SHA1 "$here/releases.json.sha1.sig" "$here/releases.json"
sign "$expiring_fpr!" SHA256 "$here/releases.json.expiring.sig" "$here/releases.json"
sign "OS Services wrong key" SHA256 "$here/releases.json.wrong-key.sig" "$here/releases.json"
sign "$subkey_fpr!" SHA256 "$here/package.bin.sig" "$here/package.bin"
sign "$expiring_fpr!" SHA256 "$here/package.bin.expiring.sig" "$here/package.bin"

gpg --armor --export "$release_fpr" > "$here/test_release_key.asc"
cat > "$here/test_release_key.h" <<HEADER
/*
 * SPDX-FileCopyrightText: 2026
 * SPDX-License-Identifier: MIT
 */

/* Generated by make_fixtures.sh: the fingerprint of the test release key in
 * test_release_key.asc. */

#pragma once

#define OSVC_TEST_ROOT_FINGERPRINT "$release_fpr"
HEADER
